INSERT INTO questions (category, type, question, options, answer, explanation, sheet) VALUES
('Operating System', 'mcq', $q$Which of the following are the four main components of a computer system?$q$, $j$["CPU, Memory, I/O devices, and Network", "Hardware, Operating System, Application Programs, Users", "Processor, RAM, Storage, Monitor", "Software, Data, Users, Network"]$j$::jsonb, 1, $q$Correct answer is option b: Hardware, Operating System, Application Programs, Users$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$The bootstrap program is typically stored in:$q$, $j$["Hard Disk", "RAM", "ROM or EPROM (firmware)", "Cache Memory"]$j$::jsonb, 2, $q$Correct answer is option c: ROM or EPROM (firmware)$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$From the user view, what is the main goal of an operating system on a personal computer?$q$, $j$["Maximize hardware resource utilization", "Provide convenience, ease of use, and good performance", "Manage user time sharing", "Execute only system commands"]$j$::jsonb, 1, $q$Correct answer is option b: Provide convenience, ease of use, and good performance$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$Which of the following is defined as "the one program running at all times on the computer" and is the core part of the operating system?$q$, $j$["Shell", "Kernel", "BIOS", "Bootloader"]$j$::jsonb, 1, $q$Correct answer is option b: Kernel$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$Which of the following is an example of a system program that is not part of the kernel?$q$, $j$["Kernel", "Memory Manager", "Shell (command interpreter)", "CPU Scheduler"]$j$::jsonb, 2, $q$Correct answer is option c: Shell (command interpreter)$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$Which of the following is an example of an application program?$q$, $j$["Linux Kernel", "Windows Task Manager", "Microsoft Word", "Disk Defragmenter"]$j$::jsonb, 2, $q$Correct answer is option c: Microsoft Word$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$Which of the following best explains why understanding the operating system is essential for writing high-performance user programs?$q$, $j$["The OS provides a graphical interface for debugging", "The OS manages hardware resources; understanding it helps optimize program behavior, memory usage, and I/O", "The OS compiles user programs into machine code", "The OS replaces the need for hardware knowledge"]$j$::jsonb, 1, $q$Correct answer is option b: The OS manages hardware resources; understanding it helps optimize program behavior, memory usage, and I/O$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$The bootstrap program is stored in firmware (ROM/EPROM) rather than on the hard disk primarily because:$q$, $j$["ROM is faster than hard disk", "ROM retains data even when power is off and is available immediately at startup", "Hard disks are not reliable during boot", "ROM can be written easily by the user"]$j$::jsonb, 1, $q$Correct answer is option b: ROM retains data even when power is off and is available immediately at startup$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$Which of the following statements about the Kernel is false?$q$, $j$["The kernel is the core part of the operating system", "The kernel runs at all times on the computer", "The kernel includes the Shell and system utilities", "The kernel acts as a bridge between user applications and hardware"]$j$::jsonb, 2, $q$Correct answer is option c: The kernel includes the Shell and system utilities$q$, 'Lecture 1'),
('Operating System', 'mcq', $q$A system program is best defined as:$q$, $j$["A program written by the user to solve a specific problem", "A program that is part of the kernel", "A program associated with the OS but not necessarily part of the kernel", "A program that compiles user code"]$j$::jsonb, 2, $q$Correct answer is option c: A program associated with the OS but not necessarily part of the kernel$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$Understanding hardware architecture and the operating system is essential for writing high-performance, reliable user programs.$q$, $j$["True", "False"]$j$::jsonb, 0, $q$The correct answer is True.$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$The bootstrap program is stored on the hard disk and is loaded when the computer starts.$q$, $j$["True", "False"]$j$::jsonb, 1, $q$The bootstrap program is stored in ROM/EPROM (firmware), not on the hard disk.$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$From the system view, the operating system acts as a resource allocator that manages resources like CPU time, memory space, and I/O devices.$q$, $j$["True", "False"]$j$::jsonb, 0, $q$The correct answer is True.$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$The Shell is part of the kernel.$q$, $j$["True", "False"]$j$::jsonb, 1, $q$The Shell is a system program associated with the OS but is not part of the kernel.$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$An Antivirus program is considered an application program.$q$, $j$["True", "False"]$j$::jsonb, 1, $q$An Antivirus program is generally considered a system utility (system program), not a regular application program.$q$, 'Lecture 1'),
('Operating System', 'truefalse', $q$The main goal of an operating system on a personal computer is to maximize resource utilization, even if it reduces convenience.$q$, $j$["True", "False"]$j$::jsonb, 1, $q$The main goal is to provide convenience, ease of use, and good performance for the user.$q$, 'Lecture 1') ON CONFLICT DO NOTHING;